## 3. Intl API for formatting

```js
// Date — locale-aware
new Intl.DateTimeFormat('tr', { dateStyle: 'long' }).format(new Date());
// '23 Mayıs 2026'

new Intl.DateTimeFormat('en-GB', { dateStyle: 'long' }).format(new Date());
// '23 May 2026'

// Number / currency
new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(1234.5);
// '1.234,50 €'

// Plural rules
const pr = new Intl.PluralRules('ru');
pr.select(1);  // 'one' → «1 вопрос»
pr.select(3);  // 'few' → «3 вопроса»
pr.select(11); // 'many' → «11 вопросов»
```

